import {financialMarkup} from './news-financial.js';
import {escapeHtml as esc} from './components.js';
import {watchButton} from './watch-button.js';
import {ideaScenarioMarkup} from './idea-scenario.js';
const safe=value=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}};
const date=v=>v&&Number.isFinite(Date.parse(v))?v.slice(0,10):'자료일 미확인';
const clock=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'분석 시각 미확인';
const citation=(s,label)=>safe(s?.url)?`<a href="${esc(safe(s.url))}" target="_blank" rel="noopener noreferrer">${esc(label)}: ${esc(s.title||s.publisher||'원문')} ↗</a><span> · ${esc(date(s.publishedAt))}</span>`:'';
const text=v=>typeof v==='string'?v:v?.text||v?.label||v?.term||v?.reason||v?.description||'';
const values=v=>(Array.isArray(v)?v:[]).map(text).filter(Boolean);
const stateLabels={QUEUED:'대기',RUNNING:'진행 중',COMPLETE:'완료',COMPLETED:'완료',PARTIAL:'부분 완료',FAILED:'실패',CANCELLED:'취소됨',SUFFICIENT:'확인 자료 확보',INSUFFICIENT:'근거 부족',NO_RESULTS:'조회 범위 내 후보 없음',NO_MATCH_IN_SCOPE:'조회 범위 내 후보 없음',EMPTY:'조회 범위 내 후보 없음',UNAVAILABLE:'외부 조회 불가',EXTERNAL_UNAVAILABLE:'외부 조회 불가',CURRENT:'현재 기준 확인',AS_OF_CHECKED:'분석 기준일 확인',HISTORICAL:'과거 자료 사용',UNKNOWN:'현재성 미확인',BUDGET_WAIT:'조회 한도 도달',STALE:'이전 기준 결과'};
Object.assign(stateLabels,{SEARCH_NO_RESULTS:'외부 검색 결과 없음',DOCUMENT_UNREADABLE:'원문 확인 불가',VERIFIED_EXTERNAL_EVIDENCE:'외부 사업 근거 확인',EXTERNAL_EVIDENCE_UNVERIFIED:'외부 근거 검증 미완료',ISSUER_UNRESOLVED:'기업 식별 미완료',EXTERNAL_NOT_NEEDED:'저장 근거로 확인',NOT_REQUESTED:'외부 조회 미요청',SEARCH_FAILED:'외부 검색 실패'});
const limitationLabels={AI_CONFIGURATION_REQUIRED:'AI 해석 설정이 없어 저장된 용어 범위에서 확인했습니다.',AI_FAILED:'AI 해석에 실패해 확인된 저장 자료만 사용했습니다.',AI_TIMEOUT:'AI 해석 시간이 초과되었습니다.',AI_RATE_LIMIT:'AI 제공자의 호출 한도로 추가 해석을 중단했습니다.',AI_TRUNCATED:'AI 응답이 중간에 끝나 추가 해석을 보류했습니다.',AI_SCHEMA_INVALID:'AI 응답 형식을 검증하지 못해 추가 해석을 보류했습니다.',AI_REFUSAL:'AI가 요청에 응답하지 않아 추가 해석을 보류했습니다.',SPECIFIC_PRODUCT_UNRESOLVED:'구체적인 제품·서비스를 식별하지 못했습니다.',LOCAL_INTERPRETATION_LIMIT:'저장된 용어로 해석할 수 있는 범위입니다. 구체적인 제품·서비스를 적어 주세요.',RETRIEVAL_LIMIT:'조회 건수 한도에 도달해 일부 저장 자료만 확인했습니다.',VERIFICATION_LIMIT:'이번 실행의 기업 검증 한도에 도달했습니다.',COUNTER_EVIDENCE_LIMIT:'반대 근거는 기업별 최근 자료의 제한된 범위에서 확인했습니다.',DOCUMENT_UNAVAILABLE:'일부 원문을 확보하지 못했습니다.',NEW_DOCUMENT_REQUIRES_ISSUER_VERIFICATION:'추가 문서는 기업 식별·주장 검증이 끝나기 전까지 결과에 반영하지 않습니다.',SEARCH_RATE_LIMIT:'검색 제공자의 호출 한도로 외부 보완을 중단했습니다.',SEARCH_FAILED:'외부 검색에 실패해 저장된 자료만 확인했습니다.',INPUT_CONDITIONS_UNRESOLVED:'입력의 일부 전제·조건을 해석하지 못했습니다.',SNAPSHOT_CHANGED:'확인 중 사업 자료가 변경되어 이전 연결을 보류했습니다.',MISSING_KEY:'외부 검색 키가 없어 저장된 자료만 확인했습니다.',DISCOVERY_LIMITED_NO_BROAD_SEARCH:'외부 검색 설정이 없어 저장된 자료 범위에서 확인했습니다.'};
Object.assign(limitationLabels,{EXTERNAL_SCOPE_LIMIT:'조회 한도 안에서 일부 제품·서비스만 외부 검색했습니다. 확인하지 못한 분야는 추가 확인이 필요합니다.',INTERPRETATION_PRODUCT_LIMIT:'질문의 사업 범위가 넓어 일부 제품·서비스만 이번 실행에서 검토했습니다.',SEARCH_NO_RESULTS:'이번 검색어·조회 범위에서 외부 자료를 찾지 못했습니다. 관련 기업이 없다는 뜻은 아닙니다.',DOCUMENT_UNREADABLE:'외부 자료를 찾았지만 원문을 읽지 못해 근거로 사용하지 않았습니다.',EXTERNAL_EVIDENCE_UNVERIFIED:'읽은 외부 자료에서 제품·사업 연결을 검증하지 못해 후보에 반영하지 않았습니다.',ISSUER_UNRESOLVED:'외부 자료의 사업 주체를 상장 기업과 정확히 연결하지 못했습니다.',EXTERNAL_NOT_NEEDED:'저장된 근거로 확인해 외부 검색은 실행하지 않았습니다.',EXTERNAL_SEARCH_LIMIT:'이번 실행의 검색 시도 한도에 도달했습니다. 캐시 조회·공식 IR 보완 검색도 한도에 포함합니다.',EXTERNAL_DOCUMENT_LIMIT:'이번 실행의 외부 원문 조회 한도에 도달했습니다. 확인한 자료만 결과에 사용했습니다.',EXTERNAL_SOURCE_IDENTITY_CONFLICT:'외부 원문의 기업·발행일 정보가 저장된 출처와 충돌해 해당 자료를 제외했습니다.'});
const limitationText=v=>limitationLabels[v]||(/^[A-Z_0-9]+$/.test(v||'')?'일부 자료의 확인을 마치지 못했습니다.':v);
const connectionLabels={DIRECT:'직접 · 제품 수요 연결',DIRECT_PRODUCT:'직접 · 제품 수요 연결',INDIRECT:'간접 · 사업 연결',INDIRECT_PRODUCT:'간접 · 사업 연결',HYPOTHETICAL:'가설적 연결',PRODUCT_DEMAND:'직접 · 제품 수요 연결',PROJECT_SUPPLY:'이번 사업 납품 연결',ECONOMIC_INFERENCE:'조건부 경제적 연결'};
const claimLabels={SUPPORTED:'원문 확인',UNVERIFIED:'검증 전',INSUFFICIENT:'근거 부족',REFUTED:'반대 근거 확인',CONTRADICTED:'반대 근거 확인',CONFLICT:'자료 상충',CONFLICTED:'자료 상충',UNKNOWN:'미확인'};
const claimReasons={EXACT_ISSUER_SERVICE_STATEMENT:'발행인 원문의 서비스 제공·운영 확인',POSITIVE_DISCLOSED_PRODUCT_SALES:'공시된 해당 제품 매출 확인',EXACT_ISSUER_SALES_STATEMENT:'발행인 원문의 제품 판매 진술 확인',EXACT_SUPPLY_STATEMENT:'원문의 납품 진술 확인',CAPABILITY_WITHOUT_SALES:'제품 생산 능력만 확인 · 판매 실적 미확인',PLAN_NOT_SALES:'판매 계획 · 실제 판매는 미확인',PRODUCT_PURPOSE_UNCONFIRMED:'제품 용도·공정 확인 필요',PERIOD_UNKNOWN:'대상 기간 미확인',NOT_KNOWN_AT_CUTOFF:'기준일 이후 공개된 자료'};
const claimReason=v=>claimReasons[v]||(/^[A-Z_]+$/.test(v||'')?'관련 근거 추가 확인 필요':v||'');
const cutoffDate=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date(v)):'미확인';
function locatorLabel(value){
 let label=String(value||'').trim();
 if(/^https?:\/\//i.test(label)){try{const u=new URL(label);label=u.hash?u.hash.slice(1):'공시 본문';}catch{label='공시 본문';}}
 try{label=decodeURIComponent(label);}catch{}
 label=label.replace(/https?:\/\/\S+/gi,'원문').replace(/[\u0000-\u001f\u007f]/g,' ').trim();
 return label.length>100?label.slice(0,99)+'…':label;
}
function inlineCandidateMarkup(c,{idea=false,quotes={}}={}){
 const a=c.asset,href=`/stock/${esc(a.market)}/${encodeURIComponent(a.ticker)}?tab=company`,quote=quotes[a.market+':'+a.ticker]||quotes[a.ticker],connection=idea&&['DIRECT','DIRECT_PRODUCT'].includes(c.connectionType)?(c.commercialStage==='SERVICE_OPERATION'?'직접 · 서비스 운영 확인':'직접 · 제품 사업 확인'):connectionLabels[String(c.connectionType||'').toUpperCase()]||text(c.connectionType),claims=[...new Map((c.claims||[]).filter(x=>x.quote).map(x=>[(x.sourceId||'')+'|'+x.quote,x])).values()].slice(0,3);
 return `<div class="nc-inline-company"><div class="nc-inline-heading"><a data-nav href="${href}">${esc(a.name)} <small>${esc(a.ticker)}${idea?' · '+(a.market==='KR'?'국내':'미국'):''}</small></a>${idea&&connection?`<span class="nc-inline-connection">${esc(connection)}</span>`:''}<span class="nc-inline-level">${esc(c.evidenceLevel||'근거 확인 중')}</span></div><p class="nc-inline-product">${esc(c.business||c.product)}</p><p><strong>연결</strong> ${esc(c.reason)}</p><p><strong>시점·조건</strong> ${esc(c.timing||'시점 미확인')} · ${esc(values(c.conditions).join(' · ')||'실제 발주·규격 확인 필요')}</p>${idea&&c.temporalStatus?`<p class="nc-inline-time">자료 유효성 · ${esc(stateLabels[String(c.temporalStatus).toUpperCase()]||c.temporalStatus)}</p>`:''}${claims.length&&idea?`<ul class="nc-idea-claims">${claims.map(x=>`<li><strong>${esc(claimLabels[String(x.status).toUpperCase()]||'주장 근거')}</strong> <q>${esc(x.quote.length>240?x.quote.slice(0,240)+'…':x.quote)}</q>${x.locator?` <small>${esc(locatorLabel(x.locator))}</small>`:''}${x.reason?`<span>${esc(claimReason(x.reason))}</span>`:''}</li>`).join('')}</ul>`:''}${c.weakening?.length?`<p class="nc-inline-caution"><strong>${idea?'반대 근거·조건부 위험':'주의'}</strong> ${esc(values(c.weakening).join(' · '))}</p>`:idea?'<p class="nc-inline-caution">확인된 반대 자료 없음 · 위험이 없다는 뜻은 아닙니다.</p>':''}${c.evidenceOrigin?`<p class="nc-inline-time">${c.evidenceOrigin==='EXTERNAL_VERIFIED'?'외부 원문 검증 후 저장':c.evidenceOrigin==='STORED'?'저장된 사업 근거 재사용':''}</p>`:''}<p class="nc-inline-citation">${citation(c.businessEvidence,'사업 근거')}${c.supplyEvidence?`<br>${citation(c.supplyEvidence,'납품 근거')}`:''}</p>${!idea?`<p class="nc-inline-direction">영향 방향 ${esc({positive:'긍정 경로 · 조건부',negative:'부정 경로',mixed:'긍정·부정 혼재',neutral:'추가 영향 미확인',unknown:'미확인'}[c.direction]||'미확인')} · 추가 매출 규모 미확인</p>`:'<p class="nc-inline-direction">제품·사업 근거의 확인 범위이며 이번 수주·이익 증가를 뜻하지 않습니다.</p>'}${financialMarkup(idea&&c.financial?{...c.financial,notice:'공시된 매출 구성입니다. 입력 가정의 추가 매출이 아니며 제품·지역 비중은 곱하지 않습니다.'}:c.financial,c.impact)}${idea?`<footer class="nc-idea-card-actions"><a data-nav href="${href}">종목 상세 →</a><button type="button" data-nc-compare="${esc(a.ticker)}" data-market="${esc(a.market)}" data-name="${esc(a.name)}">비교에 추가</button>${watchButton({...a,price:quote?.status==='ready'?quote.price:null},'',true)}</footer>`:''}</div>`;
}
export function ideaInterpretationMarkup(r){
 const i=r.interpretation||{},coverage=r.coverage||{},states=r.states||{};
 const diagnostics=r.diagnostics||{},externalState=String(states.external||'').toUpperCase(),externalAttempted=['searches','documents','externalSources'].some(k=>Array.isArray(diagnostics[k])?diagnostics[k].length>0:Number(diagnostics[k])>0)||!!externalState&&!['NOT_REQUESTED','EXTERNAL_NOT_NEEDED'].includes(externalState);
 const scope=externalAttempted?'저장 자료를 먼저 확인하고 부족한 근거는 외부에서 보완합니다. 이번 실행의 조회 한도 내 결과입니다.':coverage.scope||'저장된 자료 범위에서 확인합니다.';
 const selectedMarkets=coverage.markets||i.markets||[],selected=Array.isArray(coverage.byMarket)?coverage.byMarket.filter(m=>selectedMarkets.includes(String(m.kind).replace('_STOCK',''))):null;
 const companies=selected?selected.reduce((sum,m)=>sum+(Number(m.companies)||0),0):coverage.companies,items=selected?selected.reduce((sum,m)=>sum+(Number(m.items)||0),0):coverage.items;
 const line=(label,v)=>values(v).length?`<p><strong>${label}</strong> ${esc([...new Set(values(v))].join(' · '))}</p>`:'';
 return `<div class="nc-idea-context">${line('사용자 가정 · 외부 확인 전',i.assumptions)}${line('필수 조건',i.required)}${line('선호 조건',i.preferences)}${line('검토할 제품·사업',i.products)}${line('제품·서비스별 확인',(diagnostics.productCoverage||[]).map(p=>p.product+': '+(p.supported?'사업 근거 확인':'추가 근거 확인 필요')))}${line('검토할 경제적 변화',i.economicChanges)}${line('해석 미확인',i.unresolved)}<p class="nc-idea-state">${Object.entries(states).map(([k,v])=>`<span>${esc({execution:'실행',data:'자료',freshness:'최신성',external:'외부 보완'}[k]||k)}: ${esc(stateLabels[String(v).toUpperCase()]||'상태 확인 필요')}</span>`).join('')}</p><p class="nc-idea-scope">${selectedMarkets.length?'대상 '+selectedMarkets.map(m=>m==='KR'?'국내':m==='US'?'미국':esc(m)).join('·')+' · ':''}${Number.isInteger(companies)?'저장 기업 '+companies.toLocaleString('ko-KR')+'개 · ':''}${Number.isInteger(items)?'사업 항목 '+items.toLocaleString('ko-KR')+'개 · ':''}${esc(scope)}<br>분석 기준일 ${esc(cutoffDate(r.asOf))} · 표시 시간대 KST</p></div>`;
}
export function inlineNewsMarkup(r,options={}){
 if(!r)return '';
 const idea=r.inputType==='IDEA';
 if(idea&&r.scenario&&r.status!=='cancelled'&&(r.status!=='invalidated'||r.scenario.principlesOnly===true&&!(r.candidates?.length||r.conditional?.length||r.scenario.evidence?.length)))return ideaScenarioMarkup(r,{limitationText,stateLabels});
 if(idea){const cards=r.candidates||[],conditional=r.conditional||[];return `<section class="nc-inline nc-idea-inline" data-inline-version="${esc(r.resultVersion||r.contentVersion||'pending')}" aria-label="아이디어의 사업 연결"><p class="nc-inline-status" role="status">${esc(r.message||'저장 결과 확인 중')}</p>${ideaInterpretationMarkup(r)}${cards.length?`<h3>주요 결과 · ${cards.length}개</h3>${cards.map(c=>inlineCandidateMarkup(c,{...options,idea:true})).join('')}`:'<p class="nc-idea-empty">현재 확인한 자료에서 주요 결과를 확정하지 못했습니다.</p>'}${conditional.length?`<div class="nc-idea-conditional"><h3>조건부 연결 · ${conditional.length}개</h3><p class="nc-muted">사업 근거는 확인했지만 아래 조건이 충족되어야 연결됩니다.</p>${conditional.map(c=>inlineCandidateMarkup(c,{...options,idea:true})).join('')}</div>`:''}${values(r.limitations).length?`<div class="nc-idea-limitations"><strong>확인 범위와 한계</strong>${[...new Set(values(r.limitations).map(limitationText))].map(v=>`<p>${esc(v)}</p>`).join('')}</div>`:''}${r.sortNotice?`<p class="nc-inline-time">${esc(r.sortNotice)}</p>`:''}</section>`;}
 const cards=(r.candidates||[]).slice(0,3),kind={historical_fact:'공개된 사실',company_plan:'회사 계획',management_claim:'경영진 설명',analyst_estimate:'분석가 추정',user_assumption:'사용자 가정',system_scenario:'조건부 시나리오'}[r.claimKind];
 return `<section class="nc-inline" data-inline-version="${esc(r.resultVersion||r.contentVersion||'pending')}" aria-label="뉴스의 사업 연결"><p class="nc-inline-status" role="status">${esc(r.message||'저장 결과 확인 중')}${r.transportMessage?' · '+esc(r.transportMessage):''}</p>${r.eventSummary?`<p class="nc-inline-core"><strong>핵심</strong> ${esc(r.eventSummary)}${kind?` <span class="nc-inline-kind">${esc(kind)}</span>`:''}</p>`:''}${cards.map(c=>inlineCandidateMarkup(c)).join('')}${r.eventEvidence?`<p class="nc-inline-citation">${citation(r.eventEvidence,'기사 근거')}</p>`:''}${r.asOf?`<p class="nc-inline-time">분석 ${esc(clock(r.asOf))}</p>`:''}</section>`;
}
export function mergeInlineUpdate(article,update){
 if(update.articleId&&update.articleId!==article.id)return article;
 if(update.status==='invalidated')return {...article,relation:{...update,candidates:[]}};
 if(update.contentVersion&&article.relation?.contentVersion&&update.contentVersion!==article.relation.contentVersion)return article;
 return {...article,relation:update};
}
